import * as THREE from './vendor/three.module.js';
export function mountSolar(node,{reduced=false,onSelect=()=>{}}={}){
 node.innerHTML='';
 const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setClearColor(0x0b1026,0);renderer.domElement.setAttribute('aria-label','3D solar system illustration. Use the planet buttons below for all planet information.');renderer.domElement.setAttribute('role','img');node.append(renderer.domElement);
 const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(42,1,.1,200),group=new THREE.Group();scene.add(group);camera.position.set(0,28,39);camera.lookAt(0,0,0);scene.add(new THREE.AmbientLight(0xc8d6ff,2));const sunLight=new THREE.PointLight(0xffe6bb,100,100,1);sunLight.position.set(0,3,0);scene.add(sunLight);
 const sun=new THREE.Mesh(new THREE.SphereGeometry(2.15,40,32),new THREE.MeshBasicMaterial({color:0xffc95a}));group.add(sun);
 const glowCanvas=document.createElement('canvas');glowCanvas.width=128;glowCanvas.height=128;const ctx=glowCanvas.getContext('2d'),g=ctx.createRadialGradient(64,64,0,64,64,64);g.addColorStop(0,'rgba(255,191,63,.5)');g.addColorStop(.45,'rgba(255,160,34,.2)');g.addColorStop(1,'rgba(255,120,20,0)');ctx.fillStyle=g;ctx.fillRect(0,0,128,128);const glowTex=new THREE.CanvasTexture(glowCanvas),sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:glowTex,transparent:true,depthWrite:false}));sprite.scale.set(12,12,1);group.add(sprite);
 const data=[{r:3.5,s:.3,c:0xb5a492,speed:.9},{r:4.8,s:.5,c:0xdca855,speed:.7},{r:6.4,s:.57,c:0x548cff,speed:.5},{r:8,s:.43,c:0xc46543,speed:.4},{r:10.2,s:1.15,c:0xbc946d,speed:.23},{r:12.9,s:.95,c:0xdcc396,speed:.17},{r:15.4,s:.7,c:0x7cbfc8,speed:.13},{r:17.7,s:.68,c:0x526fe8,speed:.1}];
 const meshes=[];data.forEach((p,i)=>{const orbit=new THREE.EllipseCurve(0,0,p.r,p.r,0,Math.PI*2).getPoints(128);const geom=new THREE.BufferGeometry().setFromPoints(orbit.map(v=>new THREE.Vector3(v.x,0,v.y)));group.add(new THREE.LineLoop(geom,new THREE.LineBasicMaterial({color:0x606592,transparent:true,opacity:.3})));const mesh=new THREE.Mesh(new THREE.SphereGeometry(p.s,32,24),new THREE.MeshStandardMaterial({color:p.c,roughness:.85,metalness:.02}));mesh.userData.index=i;group.add(mesh);meshes.push(mesh);if(i===2){const land=new THREE.Mesh(new THREE.SphereGeometry(p.s*1.005,24,16,.1,1.4,.8,1.2),new THREE.MeshStandardMaterial({color:0x71be83,roughness:1}));land.rotation.z=.5;mesh.add(land);const land2=land.clone();land2.rotation.set(1.6,2.3,.8);mesh.add(land2)}if(i===4){for(let j=0;j<4;j++){const ring=new THREE.Mesh(new THREE.TorusGeometry(p.s*.94,.065,8,64),new THREE.MeshStandardMaterial({color:j%2?0xe2c4a3:0x856d59}));ring.rotation.x=Math.PI/2;ring.position.y=(j-1.5)*.28;mesh.add(ring)}}if(i===5){const ring=new THREE.Mesh(new THREE.RingGeometry(1.25,1.95,64),new THREE.MeshBasicMaterial({color:0xcbb69a,side:THREE.DoubleSide,transparent:true,opacity:.75}));ring.rotation.x=1.25;mesh.add(ring)}});
 const starPositions=[];let seed=181;function random(){seed=(seed*16807)%2147483647;return(seed-1)/2147483646}for(let i=0;i<500;i++)starPositions.push((random()-.5)*140,(random()-.5)*100,(random()-.5)*140);const starGeo=new THREE.BufferGeometry();starGeo.setAttribute('position',new THREE.Float32BufferAttribute(starPositions,3));scene.add(new THREE.Points(starGeo,new THREE.PointsMaterial({color:0xc3cbff,size:.1,transparent:true,opacity:.7})));
 let frame,time=8,paused=reduced,dead=false,selected=2;const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),clock=new THREE.Clock();const highlight=new THREE.Mesh(new THREE.RingGeometry(.8,.84,48),new THREE.MeshBasicMaterial({color:0xb7ff45,side:THREE.DoubleSide,transparent:true,opacity:.9}));highlight.rotation.x=-Math.PI/2;group.add(highlight);
 const resize=()=>{const w=Math.max(1,node.clientWidth),h=innerWidth<=650?365:470;renderer.setSize(w,h);camera.aspect=w/h;camera.fov=w/h<1.1?65:42;camera.updateProjectionMatrix()};const observer=new ResizeObserver(resize);observer.observe(node);resize();
 let dragging=false,startX=0,startY=0,lastX=0,lastY=0,moved=0;const down=e=>{dragging=true;startX=lastX=e.clientX;startY=lastY=e.clientY;moved=0};const move=e=>{if(!dragging)return;const dx=e.clientX-lastX,dy=e.clientY-lastY;group.rotation.y+=dx*.008;group.rotation.x=THREE.MathUtils.clamp(group.rotation.x+dy*.003,-.25,.45);lastX=e.clientX;lastY=e.clientY;moved=Math.hypot(e.clientX-startX,e.clientY-startY)};const up=e=>{if(!dragging)return;dragging=false;if(moved>8)return;const rect=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObjects(meshes,false)[0];if(hit){selected=hit.object.userData.index;onSelect(selected)}};
 const select=e=>{if(Number.isInteger(e.detail)&&data[e.detail])selected=e.detail};const toggle=()=>{paused=!paused};const reset=()=>{group.rotation.set(0,0,0);time=8;selected=2;onSelect(2)};
 renderer.domElement.addEventListener('pointerdown',down);window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);window.addEventListener('zuno-planet',select);window.addEventListener('zuno-orbit-toggle',toggle);window.addEventListener('zuno-orbit-reset',reset);
 function animate(){if(dead)return;frame=requestAnimationFrame(animate);const delta=Math.min(clock.getDelta(),.05);if(!paused&&!document.hidden)time+=delta*.32;meshes.forEach((m,i)=>{const p=data[i],a=time*p.speed+i*.9;m.position.set(Math.cos(a)*p.r,0,Math.sin(a)*p.r);if(!paused)m.rotation.y+=delta*.1});const m=meshes[selected];highlight.position.copy(m.position);highlight.position.y=-.08;highlight.scale.setScalar(data[selected].s/.57);renderer.render(scene,camera)}animate();
 return()=>{dead=true;cancelAnimationFrame(frame);observer.disconnect();renderer.domElement.removeEventListener('pointerdown',down);window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);window.removeEventListener('zuno-planet',select);window.removeEventListener('zuno-orbit-toggle',toggle);window.removeEventListener('zuno-orbit-reset',reset);scene.traverse(o=>{o.geometry?.dispose();if(o.material){for(const m of(Array.isArray(o.material)?o.material:[o.material]))m.dispose()}});glowTex.dispose();renderer.dispose();renderer.forceContextLoss()};
}
